<script>
const PAGE_SIZE_DEFAULT = 10;
import VueCookies from "vue-cookies";
import { eventBus } from "@/main";
import PositionSpecification from "../shared/PositionSpecification.vue";
export default {
  name: "OpenPositions",

  components: { PositionSpecification },

  data() {
    return {
      positions: [],
      total: 0,
      page: 1,
      count: PAGE_SIZE_DEFAULT,
      loading: true,
      searchTimer: null,
      filter: {
        name: "",
        openOnly: false,
      },
      drawer: {
        open: false,
        pos: {},
      },
      authDialog: false,
      pendingPos: null,
      wasGuestLogin: false,
    };
  },

  computed: {
    // PositionSpecification expects a raw FHIR resource with an `extension`
    // array — the drawer only carries the position's extracted extensions,
    // so wrap them back into a minimal resource shape here.
    drawerPositionResource() {
      return { extension: this.drawer.pos.positionExtensions || [] };
    },

    totalPages() {
      return Math.max(1, Math.ceil(this.total / this.count));
    },

    pageRange() {
      const total = this.totalPages;
      const cur = this.page;
      if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1);
      const pages = [];
      if (cur > 3) {
        pages.push(1);
        if (cur > 4) pages.push("…");
      }
      for (let p = Math.max(1, cur - 1); p <= Math.min(total, cur + 1); p++) {
        pages.push(p);
      }
      if (cur < total - 2) {
        if (cur < total - 3) pages.push("…");
        pages.push(total);
      }
      return pages;
    },
  },

  methods: {
    login() {
      let formData = new URLSearchParams();
      formData.append("username", "guest@health.gov.ls");
      formData.append("password", "AN{d(X3rjP5vV8KhkHyB^9");
      return fetch("/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: formData,
      }).then(() => {
        eventBus.$emit("updateconfig");
        this.loggedin = true;
        this.overlay = false;
      });
    },
    logout() {
      if (this.$store.state.idp === "keycloak") {
        VueCookies.remove("userObj");
        this.$keycloak.logout();
      } else {
        fetch("/auth/logout").then(() => {
          this.$store.commit("logout");
          this.$emit("loggedout");
        });
      }
    },
    async load() {
      this.loading = true;
      try {
        const offset = (this.page - 1) * this.count;
        const params = new URLSearchParams({
          _count: this.count,
          _getpagesoffset: offset,
        });
        if (this.filter.name.trim())
          params.set("name", this.filter.name.trim());
        if (this.filter.openOnly) params.set("openOnly", "true");

        const res = await fetch(
          `/site/unauthenticated/open-vacancies?${params}`,
        );
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        this.positions = data.advertisements || [];
        this.total = data.total || 0;
      } catch (err) {
        console.error("open-vacancies load error", err);
        this.positions = [];
        this.total = 0;
      } finally {
        this.loading = false;
      }
    },

    resetAndLoad() {
      this.page = 1;
      this.load();
    },

    onSearchInput() {
      clearTimeout(this.searchTimer);
      this.searchTimer = setTimeout(() => this.resetAndLoad(), 400);
    },

    clearSearch() {
      this.filter.name = "";
      this.resetAndLoad();
    },

    clearFilters() {
      this.filter.name = "";
      this.filter.openOnly = false;
      this.resetAndLoad();
    },

    onCountChange(val) {
      this.count = val;
      this.page = 1;
      this.load();
    },

    statusLabel(status) {
      return (
        { open: "Open", closed: "Apps Closed", pending: "Not Yet Open" }[
          status
        ] || status
      );
    },

    daysRemaining(closingDate) {
      if (!closingDate) return 0;
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const close = new Date(closingDate);
      return Math.round((close - today) / 86400000);
    },

    formatDate(dateStr) {
      if (!dateStr) return "—";
      const d = new Date(dateStr);
      return d.toLocaleDateString("en-GB", {
        day: "numeric",
        month: "short",
        year: "numeric",
      });
    },

    truncate(str, len) {
      if (!str) return "";
      return str.length <= len ? str : str.slice(0, len).trimEnd() + "…";
    },

    openDetail(pos) {
      this.drawer.pos = pos;
      this.drawer.open = true;
      document.body.style.overflow = "hidden";
    },

    closeDetail() {
      this.drawer.open = false;
      document.body.style.overflow = "";
    },

    applyOrPrompt(pos) {
      this.closeDetail();
      const role = this.$store.state?.user?.obj?.resource?.extension
        ?.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-assign-role",
        )
        ?.valueReference?.reference?.split("/")?.[1];

      if (
        role &&
        role !== "ihris-role-guest" &&
        this.$store.state.user.loggedin
      ) {
        this.applyFor(pos);
      } else {
        this.pendingPos = pos;
        this.authDialog = true;
      }
    },

    goToLogin() {
      this.logout();
      this.authDialog = false;
      this.$router.push({ path: "/" });
    },

    goToSignup() {
      this.authDialog = false;
      this.$router.push({
        path: "/custom/signup",
        query: {
          path: "/lesotho/components/recruitment",
          ...(this.pendingPos ? { advertId: this.pendingPos.id } : {}),
        },
      });
    },

    applyFor(pos) {
      this.$emit("apply", pos);
      // Default: navigate to application form route if no parent handles it
      if (!this.$listeners || !this.$listeners.apply) {
        this.$router
          .push({
            path: "/custom/apply-for-position",
            query: {
              path: "/lesotho/components/recruitment",
              advertId: pos.id,
            },
          })
          .catch(() => {});
      }
    },
  },

  async mounted() {
    // Start fetching positions immediately — endpoint is public, no auth needed
    const loadPromise = this.load();

    // Give Vuex time to rehydrate from the server session before deciding
    // to log in as guest. Without this delay, a page reload sees an empty
    // store and incorrectly overwrites the real user's session.
    await this.$nextTick();
    await new Promise((r) => setTimeout(r, 400));

    if (
      !this.$store.state?.user?.obj?.resource ||
      !this.$store.state.user.loggedin
    ) {
      await this.login();
      this.wasGuestLogin = true;
    }

    await loadPromise;
  },
  created() {
    eventBus.$on("Basic.nationality", (val) => {
      this.form.nationality = val;
    });
  },
  beforeDestroy() {
    // Only logout the guest session if this component was the one that
    // created it. Never touch a real user's session.
    if (this.wasGuestLogin && this.$route.path !== "/custom/signup") {
      this.logout();
    }
    clearTimeout(this.searchTimer);
    document.body.style.overflow = "";
  },
};
</script>

